      const el = sc.slice(0, 6).map(s => s[1]), tour = () => { let b = null; for (let i = 0; i < 3; i++) { const c = sc[Math.floor(R() * sc.length)]; if (!b || c[0] > b[0]) b = c; } return b[1]; };
