      Pos = Array.from({ length: n }, () => vec(d, 0.5)); q = vec(d, 0.3); g = 1;
      const U = d + n * d + (P.rel ? n * (n - 1) / 2 : 0); W1 = Array.from({ length: H }, () => vec(U, 1 / Math.sqrt(U))); b1 = new Array(H).fill(0);
