  const exprs = (x, a) => { const out = []; x.forEach((t, j) => { if (t === a) out.push('c' + j); });
    if (num && val(a) != null) x.forEach((t, j) => { const v = val(t); if (v != null && v !== val(a)) { const c = val(a) - v; if (Math.abs(c) <= 3) out.push('p' + j + ':' + c); } });
